//! Per-family advance tables, generated from the host's own font files.
//!
//! A CSS family this list carries answers the advances macOS's font for it
//! answers, pair adjustments included; a family it does not carry keeps the
//! bundled stand-in's metrics. Regenerate with `tools/gen_font_tables.py`.

/// One family: advances in font units for ASCII and Latin-1, plus the kern
/// pairs between the covered characters keyed as `(first << 16) | second`.
pub struct FontTable {
    pub family: &'static str,
    pub upem: f32,
    pub ascii: &'static [f32],
    pub latin1: &'static [f32],
    pub kern: &'static [(u32, i16)],
}

impl FontTable {
    /// The advance for one character in the table's units, or `None` when the
    /// table does not carry it (a value of zero means the face has no glyph
    /// for the character, which keeps the shaped stand-in's advance instead).
    pub fn advance(&self, ch: char) -> Option<f32> {
        let code = ch as u32;
        let value = if (0x20..=0x7E).contains(&code) {
            self.ascii.get((code - 0x20) as usize).copied()
        } else if (0xA0..=0xFF).contains(&code) {
            self.latin1.get((code - 0xA0) as usize).copied()
        } else {
            None
        }?;
        if value == 0.0 {
            return None;
        }
        Some(value)
    }

    /// The kern adjustment between two adjacent characters, in the table's
    /// units, zero when the pair carries none.
    pub fn kern(&self, first: char, second: char) -> f32 {
        let key = ((first as u32) << 16) | (second as u32);
        self.kern
            .iter()
            .find(|(pair, _)| *pair == key)
            .map_or(0.0, |(_, value)| *value as f32)
    }

    /// The bold variant of this family's advance table. Only `system-ui`
    /// carries one today: Chrome's SF bold is measurably wider than its
    /// regular (an sf text probe answers `tttt hhhh` 60.98 bold against 54.77
    /// through the old table), while every other family's bold is unmeasured
    /// and falls back to the regular values, which is the established
    /// behaviour. The empty placeholder keeps the fallback until the measured
    /// table replaces it.
    pub fn bold_variant(&'static self) -> &'static FontTable {
        if self.family.eq_ignore_ascii_case("system-ui") && !SYSTEM_UI_BOLD.ascii.is_empty() {
            &SYSTEM_UI_BOLD
        } else {
            self
        }
    }
}

