    /// Every family whose table does not reproduce the reference, with
    /// the reason the generator recorded for it.
    const RESIDUAL_FAMILIES: &[&str] = &[
        "Helvetica Neue: measured table, probe off by +0.0179px",
        "Zapfino: measured table, probe off by -0.3933px",
        "InaiMathi: measured table, probe off by +0.0223px",
        "Apple LiGothic: measured table, probe off by +0.0118px",
        "Songti SC: measured table, probe off by +0.0141px",
        "Ayuthaya: measured table, probe off by +0.0236px",
        "Sathu: measured table, probe off by -0.0142px",
        "Yuanti SC: measured table, probe off by +0.0113px",
    ];

    #[test]
    fn tables_reproduce_the_reference_widths() {
        assert!(!CASES.is_empty());
        for (family, generated, reference) in CASES {
            assert!(
                (generated - reference).abs() < 0.01,
                "{family}: generated {generated}, reference {reference}"
            );
            assert!(table_for_family(family).is_some(), "{family} is missing");
        }
    }

    /// Every table is either a case above or a documented residual, so a
    /// regeneration cannot quietly drop one family and add another.
    #[test]
    fn every_family_is_matching_or_documented() {
        for table in FONT_TABLES {
            let matching = CASES.iter().any(|(name, _, _)| *name == table.family);
            let residual = RESIDUAL_FAMILIES
                .iter()
                .any(|line| line.starts_with(table.family));
            assert!(matching || residual, "{} is in neither list", table.family);
        }
    }
